// Writes src/styles/tokens.css from @kavtsya/shared/design-tokens.json, the same
// file the app's theme is built from (ADR 0020). The output is git-ignored and
// regenerated by every build, so the site cannot drift from the app's tokens.
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const kebab = (key) => key.replace(/([a-z])([A-Z])/g, "$1-$2").toLowerCase();

/** `{color.neutral.50}` aliases resolve to the referenced token's final value. */
function resolveAlias(tokens, value) {
  if (typeof value !== "string" || !value.startsWith("{")) return value;
  const target = value
    .slice(1, -1)
    .split(".")
    .reduce((node, key) => node[key], tokens);
  return resolveAlias(tokens, target.$value);
}

/** Dimensions become `rem` so text and spacing scale with the browser's font size. */
function rem(value) {
  const px = /^(-?\d+(?:\.\d+)?)px$/.exec(value);
  if (!px) return value;
  const n = parseFloat(px[1]) / 16;
  return n === 0 ? "0" : `${n}rem`;
}

function cssValue(token, tokens) {
  const value = resolveAlias(tokens, token.$value);
  switch (token.$type) {
    case "fontFamily":
      return value
        .map((name) => (/^[\w-]+$/.test(name) ? name : `"${name}"`))
        .join(", ");
    case "shadow": {
      const { offsetX, offsetY, blur, spread, color } = value;
      return [offsetX, offsetY, blur, spread].map(rem).join(" ") + ` ${color}`;
    }
    case "dimension":
      return rem(value);
    default:
      return String(value);
  }
}

/** One `--a-b-c: value;` declaration per leaf token, named from its path. */
function declarations(node, prefix, tokens) {
  const out = [];
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    const name = `${prefix}-${kebab(key)}`;
    if (child.$value !== undefined) {
      out.push(`  ${name}: ${cssValue(child, tokens)};`);
    } else {
      out.push(...declarations(child, name, tokens));
    }
  }
  return out;
}

export function buildTokensCss(tokens) {
  const primitives = [
    "color",
    "font",
    "space",
    "radius",
    "shadow",
    "motion",
  ].flatMap((group) => declarations(tokens[group], `--${group}`, tokens));
  const light = declarations(tokens.semantic.light, "--semantic", tokens);
  const dark = declarations(tokens.semantic.dark, "--semantic", tokens);
  return [
    "/* AUTO-GENERATED from @kavtsya/shared/design-tokens.json by scripts/build-tokens-css.mjs. Do not edit. */",
    ":root {",
    ...primitives,
    ...light,
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    ...dark.map((line) => `  ${line}`),
    "  }",
    "}",
    "",
  ].join("\n");
}

function main() {
  const src = createRequire(import.meta.url).resolve(
    "@kavtsya/shared/design-tokens.json",
  );
  const out = path.join(
    path.dirname(fileURLToPath(import.meta.url)),
    "..",
    "src",
    "styles",
    "tokens.css",
  );
  const tokens = JSON.parse(fs.readFileSync(src, "utf8"));
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, buildTokensCss(tokens));
  console.log(`tokens:build → ${path.relative(process.cwd(), out)}`);
}

if (
  process.argv[1] &&
  fs.realpathSync(process.argv[1]) ===
    fs.realpathSync(fileURLToPath(import.meta.url))
)
  main();
